function twoSum(nums, target):
    seen = empty map
    for each (index, value) in nums:
        need = target - value
        if need exists in seen:
            return [seen[need], index]
        seen[value] = index
    return []

function merge(intervals):
    if intervals is empty: return []
    sort intervals by start
    result = [copy of intervals[0]]
    for interval in intervals[1:]:
        last = result.last
        if interval.start <= last.end: last.end = max(last.end, interval.end)
        else: append copy of interval to result
    return result

